<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('[data-artwork-media-upload]'),items=form?.querySelector('[data-media-items]'),template=form?.querySelector('[data-media-template]'),add=form?.querySelector('[data-add-media]');if(form){let index=1;const sync=()=>{const rows=[...items.querySelectorAll('[data-media-row]')];rows.forEach(row=>{const remove=row.querySelector('[data-remove-media]');remove.hidden=rows.length===1;remove.onclick=()=>{row.remove();sync()}});add.disabled=rows.length>=8};add.addEventListener('click',()=>{if(items.children.length>=8)return;const wrapper=document.createElement('div');wrapper.innerHTML=template.innerHTML.replaceAll('__INDEX__',String(index++)).trim();items.appendChild(wrapper.firstElementChild);sync()});sync()}const list=document.querySelector('[data-managed-media-list]');if(!list)return;const syncOrder=()=>{const rows=[...list.querySelectorAll('[data-managed-media-item]')];rows.forEach((row,index)=>{const up=row.querySelector('[data-move-media="up"]'),down=row.querySelector('[data-move-media="down"]');up.disabled=index===0;down.disabled=index===rows.length-1})};list.addEventListener('click',event=>{const button=event.target.closest('[data-move-media]');if(!button)return;const row=button.closest('[data-managed-media-item]');if(button.dataset.moveMedia==='up'&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);if(button.dataset.moveMedia==='down'&&row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);syncOrder()});syncOrder()});</script>
